export const ptOverviews: Record<string, string> = {
	'moolchand-hospital':
		'O Moolchand Medcity é um grupo hospitalar multiespecialidade com unidades no sul de Deli e em Agra, que serve pacientes há cerca de seis décadas. O centro do sul de Deli reúne mais de 250 médicos em mais de 50 especialidades, incluindo urgência, cardiologia, neurociências, ortopedia, cuidados renais e diálise, gastroenterologia, pediatria e um instituto da mulher. Foi um dos primeiros hospitais indianos a realizar cirurgia minimamente invasiva e laparoscópica, e tem acreditações JCI, NABH, NABL e ISO.',
	'fortis-c-doc-hospital':
		'O Fortis C-DOC é um centro de excelência compacto, com 23 camas, dedicado à diabetes, às doenças metabólicas e à endocrinologia, dirigido pelo Prof. Anoop Misra e ativo nesta área desde 2011. Dispõe de dois blocos operatórios, um centro de pé diabético e tratamento de feridas, um laboratório oftalmológico para diabéticos e um centro de diálise. Oferece ainda programas de controlo de peso com cirurgia bariátrica e minimamente invasiva, apoiados por laboratório, radiologia e farmácia 24 horas por dia.',
	'fortis-escorts-heart-institute':
		'O Fortis Escorts Heart Institute é um hospital de 310 camas reconhecido mundialmente pelas ciências cardíacas, que celebrou 25 anos de cuidados cardíacos em 2013. O seu programa cardíaco abrange angioplastias complexas, TAVR, pacing e eletrofisiologia, cirurgia cardíaca de adultos e crianças, cirurgia minimamente invasiva e robótica, LVAD e transplante cardíaco. O hospital trata também doenças digestivas, pancreáticas e hepáticas, incluindo transplantes de fígado.',
	'fortis-flt-lt-rajan-dhall-hospital':
		'O Fortis Flt. Lt. Rajan Dhall Hospital, em Vasant Kunj, é um hospital multiespecialidade com mais de 162 camas no sul de Deli, a cerca de 8 km do aeroporto internacional. Oferece cerca de 30 especialidades, com centros dedicados a ciências cardíacas, ortopedia e prótese articular, ciências renais, oncologia, reumatologia, pneumologia e cuidados críticos, e ciências bariátricas. As clínicas especializadas abrangem asma e alergias, cálculos renais, obesidade, lesões desportivas e menopausa.',
	'blk-max-super-speciality-hospital':
		'O BLK-Max é um dos maiores hospitais privados de cuidados terciários da Índia: ocupa cinco acres, tem 650 camas e uma história que remonta a 1959. Tem centros dedicados ao cancro, transplante de medula óssea, coração, neurociências, doenças digestivas e hepáticas, ciências renais e transplante de rim, ortopedia e prótese articular, doenças respiratórias e cuidados críticos. Tem também programas de transplante de medula óssea, fígado, rim e coração, e está acreditado pela JCI, NABH e NABL.',
	'artemis-hospital':
		'O Artemis Hospital, fundado pelo Apollo Tyres Group e inaugurado em 2007, é descrito como o primeiro hospital acreditado pela JCI em Gurugram. Este hospital de mais de 600 camas, num campus de 9 acres, reúne especialistas em mais de 40 disciplinas, incluindo cardiologia, oncologia, neurociências, ortopedia, nefrologia, gastroenterologia, urologia e transplante de órgãos. A cirurgia robótica com o sistema da Vinci e serviços de neurociências como Gamma Knife e estimulação cerebral profunda estão entre os seus pontos fortes.',
	'max-super-speciality-hospital-saket':
		'O Max Super Speciality Hospital, Saket, é um hospital com mais de 514 camas no sul de Deli, organizado em dois blocos, Este e Oeste. Tem 25 blocos operatórios modulares, mais de 170 camas de cuidados críticos, uma unidade de diálise avançada, uma unidade de oncologia em ambulatório e mais de 680 especialistas em 32 especialidades. Os seus centros abrangem cuidados cardíacos, oncologia, transplantes (coração, pulmão e medula óssea), cirurgia minimamente invasiva e bariátrica, e está acreditado como centro de excelência em cirurgia bariátrica e de hérnias.',
	'indraprastha-apollo-hospitals':
		'O Indraprastha Apollo Hospitals, inaugurado em 1996, é o hospital de referência da Apollo em Deli, com 15 acres, 710 camas operacionais e mais de 250 camas de cuidados intensivos. Gere um dos programas de transplante de fígado e rim mais ativos da Índia, uma unidade de transplante de medula óssea e transplantes multiorgânicos, incluindo coração, pâncreas e casos pediátricos. O seu centro oncológico completo oferece braquiterapia HDR e tomoterapia, além do primeiro centro de protonterapia da Índia, e o hospital utiliza o sistema de cirurgia robótica da Vinci.',
	'apollo-spectra-hospitals':
		'O Apollo Spectra Deli tem dois centros, em Karol Bagh e Chirag Enclave, focados em especialidades cirúrgicas e de hospital de dia. Os seus serviços incluem cirurgia geral e laparoscópica, ortopedia e coluna, urologia, varizes, cirurgia bariátrica, ginecologia e otorrinolaringologia. Cada centro dispõe de blocos operatórios modulares modernos, sala de endoscopia, unidade de cuidados críticos, farmácia, diagnóstico e radiologia, com cerca de 60 médicos consultores especialistas.',
	'batra-hospital-medical-research-centre':
		'O Batra Hospital & Medical Research Centre foi criado em 1987 como o primeiro hospital multiespecialidade privado de Deli e foi inaugurado pelo então primeiro-ministro Rajiv Gandhi. Tornou-se um hospital de cuidados terciários de 500 camas, com 14 blocos operatórios, cerca de 110 camas de UCI e urgência 24 horas em 42 especialidades. Criou alguns dos primeiros centros de excelência privados em oncologia, cardiologia e nefrologia, além de neurociências, gastroenterologia e transplante renal.',
	'aakash-healthcare-super-speciality-hospital':
		'O Aakash Healthcare, fundado em 2011 em Dwarka, é um hospital de cuidados terciários com 230 camas, 70 camas de cuidados críticos e 15 postos de diálise. É particularmente conhecido pela ortopedia e prótese articular, e gere centros de excelência em cardiologia, cirurgia geral e minimamente invasiva, oftalmologia e cirurgia refrativa, cuidados materno-infantis, neurociências e ciências renais. O hospital está acreditado pela NABH e NABL e tem convénio com a CGHS.',
	'manipal-hospital-dwarka':
		'O Manipal Hospital Dwarka é um hospital terciário multi-superespecialidade que serve o oeste de Deli, com 13 blocos operatórios modulares e 118 camas de cuidados críticos. Os seus centros de excelência abrangem ortopedia e prótese articular, ciências renais, ciências cardíacas, gastroenterologia, neurociências, oncologia, e ginecologia e pediatria, com transplante hepático e cuidados oncológicos dedicados. A tecnologia inclui cirurgia robótica, imagem O-arm, telemedicina e registo clínico eletrónico, e o hospital tem acreditação NABH e NABL.',
	'sir-ganga-ram-hospital':
		'O Sir Ganga Ram Hospital, nome do engenheiro e filantropo Sir Ganga Ram, serve Deli desde 1954 e tem cerca de 675 camas. Os seus departamentos incluem cardiologia e o Dharma Vira Heart Centre, oncologia, gastroenterologia, ortopedia, neurologia, medicina genética, cirurgia minimamente invasiva e bariátrica, transplante de fígado e implantes cocleares. O departamento de nefrologia começou em 1981 e o primeiro transplante de rim foi realizado em 1987; hoje realizam-se cerca de 250 transplantes por ano.',
	'amrita-hospital':
		'O Amrita Hospital em Faridabad abriu em agosto de 2022 com 2600 camas, como hospital terciário, multiespecialidade e de superespecialidades. Tem oito centros de excelência: cancro, ciências cardíacas, neurociências, doenças digestivas, ortopedia e prótese articular, ciências renais, transplante de órgãos sólidos e cuidados materno-infantis. Dispõe de 534 camas de cuidados críticos monitorizadas por IA, imagem avançada como PET-TC e RM de 3T, e é reconhecido pela cirurgia robótica de dador hepático.',
	'metro-heart-institute-with-multispeciality':
		'O Metro Heart Institute, em Faridabad, funciona desde 2002 como o primeiro hospital cardíaco dedicado de Haryana e tem hoje mais de 400 camas e mais de 30 especialidades. A sua equipa cardíaca realizou mais de 75 000 angiografias e angioplastias e mais de 10 000 cirurgias cardíacas, e introduziu o TAVI e a cirurgia cardíaca minimamente invasiva na região. O hospital oferece também transplante de rim, transplante de medula óssea e mamografia, e tem acreditação NABH e NABL.',
	'the-sight-avenue':
		'O The Sight Avenue é um hospital oftalmológico de superespecialidade fundado pelo Dr. Suraj Munjal, com centros em Greater Kailash (Nova Deli) e no Setor 38 de Gurugram. Oferece cirurgia de cataratas, incluindo técnicas laser sem lâmina, LASIK, Contoura Vision, SMILE, lentes de colâmero implantáveis, retina e úvea, glaucoma, córnea e ceratocone, estrabismo, oculoplástica e oftalmologia pediátrica. O hospital refere ter tratado mais de 50 000 pacientes.',
	'shroff-eye-centre':
		'O Shroff Eye Centre presta cuidados oculares completos nos centros de Kailash Colony e Connaught Place; o Dr. Cyrus Shroff integra a equipa desde 1984. Realiza cirurgia de cataratas por facoemulsificação sem pontos com lentes premium, cirurgia refrativa (LASIK, Femto Contoura, SILK, ICL e PRK), cirurgia vitreorretiniana, cuidados de córnea e glaucoma, oftalmologia pediátrica e uma clínica dedicada ao olho seco. Como centro oftalmológico terciário, realiza mais de 10 000 cirurgias por ano.',
	'eye7-hospitals':
		'O Eye7 Eye Hospitals é uma rede de centros de cuidados oculares em Deli-NCR, com mais de 30 anos de prática e mais de 200 000 cirurgias acumuladas. Os seus serviços incluem LASIK sem lâmina com laser de femtossegundo e Contoura Vision, ICL EVO, troca de cristalino, cataratas, glaucoma, retina, córnea, estrabismo, neuro-oftalmologia, oculoplástica, oftalmologia pediátrica e baixa visão. Os hospitais estão acreditados pela NABH e constam das listas da CGHS, ECHS e outros programas públicos.',
	'sharp-sight-eye-hospitals':
		'O Sharp Sight Eye Hospitals, fundado em 1998, é uma cadeia de centros oftalmológicos do norte da Índia, acreditada pela NABH e reconhecida pela CGHS. Oferece cirurgia de cataratas com técnicas convencionais e laser avançadas, LASIK sem lâmina, tratamento do glaucoma, do estrabismo e do olho preguiçoso, cuidados da retinopatia diabética, serviços de córnea e oftalmologia pediátrica. Exames da retina como FFA, ecografia B e OCT apoiam os seus cirurgiões de retina.',
	'venu-eye-institute-research-centre':
		'O Venu Eye Institute & Research Centre é um hospital oftalmológico num campus de 2,5 acres em Sheikh Sarai, no sul de Deli, que atende sob o mesmo teto pacientes pagantes e pacientes subsidiados. Os serviços incluem cirurgia de cataratas e refrativa, LASIK, tratamento de córnea, glaucoma e retina, oculoplástica, cirurgia de tumores da órbita, cirurgia de estrabismo e lentes de contacto. Em mais de 40 anos tratou milhões de pacientes, muitos gratuitamente ou a preços subsidiados, e forma também profissionais de oftalmologia.',
	'guru-nanak-eye-centre':
		'O Guru Nanak Eye Centre é um instituto oftalmológico público de Deli, concebido em 1971 e com o bloco de consultas externas operacional desde 1977. Tem seis unidades oftalmológicas, enfermarias e blocos operatórios, e oferece clínicas de superespecialidade de córnea, retina, glaucoma, neuro-oftalmologia, oftalmologia pediátrica, estrabismo e lentes de contacto. As consultas externas são gratuitas e uma equipa numerosa de oftalmologistas atende os pacientes todos os dias.',
	'shining-smile-dentistry':
		'A Shining Smiles Dentistry, em Saket (Nova Deli), abriu em 2021 e é conhecida pelos implantes dentários, implantes imediatos e transformações do sorriso. Os seus serviços incluem design de sorriso Hollywood, design digital do sorriso, facetas, Invisalign, coroas, elevação do seio e enxertos ósseos, além de endodontia com microscópio. As salas de tratamento usam radiografia digital, scanners 3D e câmaras intraorais para um diagnóstico e planeamento precisos.',
	'spruce-dental-chain-of-clinics':
		'A Spruce Dental Chain of Clinics, dirigida pelo Dr. Javed Rizwan, é uma clínica de implantologia e ortodontia situada atrás do Medanta Hospital em Gurugram, também conhecida como Smile Garden Dental Implant Center. Oferece implantes imediatos e convencionais de titânio ou zircónia, endodontia, design do sorriso, aparelhos e alinhadores, e reabilitação completa da boca. O Dr. Rizwan tem mais de 20 anos de experiência e um mestrado em implantologia estratégica obtido na Alemanha.',
	'asg-eye-hospital':
		'O ASG Eye Hospital é uma cadeia de hospitais oftalmológicos de superespecialidade fundada em 2005 em Jodhpur pelos Drs. Arun Singhvi e Shilpi Gang, hoje presente em muitas cidades da Índia. O centro de Noida trata cataratas com lentes premium, LASIK (incluindo Contoura e PRK), glaucoma, doenças da retina como a retinopatia diabética, córnea, estrabismo, oculoplástica, oftalmologia pediátrica e neuro-oftalmologia, tudo sob o mesmo teto.',
	'eye-q-super-speciality-eye-hospitals':
		'O Eye-Q começou em 2007 como uma única unidade e tornou-se uma cadeia de hospitais oftalmológicos de superespecialidade no norte da Índia, com vários centros em Gurugram, incluindo Golf Course Road e DLF Cyber City. Os serviços incluem cirurgia de cataratas com laser sem lâmina, LASIK, cuidados da retina com fotocoagulação a laser e crioterapia, glaucoma, oculoplástica, neuro-oftalmologia, estrabismo, além de ótica e farmácia próprias.',
	'medanta-the-medicity':
		'O Medanta – The Medicity, fundado pelo cirurgião cardíaco Dr. Naresh Trehan em 2009, é um dos maiores hospitais multi-superespecialidade da Índia, com 29 unidades de superespecialidade e mais de 800 médicos. Os seus seis centros de excelência abrangem ciências cardíacas, neurociências, osso e articulação, cancro, ciências renais e urologia, e transplante de fígado. Refere mais de 500 transplantes hepáticos de dador vivo, utiliza o sistema robótico da Vinci e é classificado como o melhor hospital privado da Índia pela Newsweek (World\'s Best Hospitals).',
	'fortis-memorial-research-institute-fmri':
		'O Fortis Memorial Research Institute é um hospital multi-superespecialidade de cuidados quaternários perto de HUDA City Centre, em Gurugram, acreditado pela JCI, NABH e NABL. Os seus centros de excelência incluem cirurgia robótica, oncologia, cardiologia e cirurgia cardíaca, transplantes de rim e fígado, hematologia e transplante de medula óssea, gastroenterologia, neurociências, urologia, ortopedia e prótese articular, e cirurgia bariátrica. Realizaram-se aqui mais de 2500 transplantes de medula óssea.',
	'sanar-international-hospitals':
		'O Sanar International Hospitals, agora Shalby Sanar International Hospital, é um hospital multiespecialidade em Golf Course Road, Gurugram, acreditado pela JCI e NABH. Oferece cuidados oncológicos, cardíacos, transplantes de medula óssea, rim e fígado, e é sobretudo conhecido pela ortopedia e prótese articular, apoiado pela experiência do grupo Shalby, com mais de 150 000 próteses articulares. A equipa realiza também cirurgia de revisão da anca e do joelho com navegação por computador e implantes especiais.',
	'jaypee-hospital':
		'O Jaypee Hospital é o hospital terciário de referência do Grupo Jaypee, num campus de 25 acres no Setor 128 de Noida, com mais de 525 camas operacionais, mais de 150 camas de UCI e 18 blocos operatórios modulares. Oferece mais de 30 superespecialidades, com um instituto do coração com salas de hemodinâmica híbridas e um instituto de transplante de órgãos (fígado, rim, coração, córnea e medula óssea), apoiado por uma UCI de transplantes de 12 camas. Dispõe de cirurgia robótica com o sistema da Vinci em urologia, ginecologia e cirurgia geral.',
	'marengo-asia-hospitals':
		'O Marengo Asia Hospitals em Faridabad, antes QRG Health City, é um hospital terciário multi-superespecialidade de 450 camas, criado em 2007 e acreditado pela NABH e NABL. As suas especialidades incluem oncologia, ciências cardíacas, gastroenterologia, transplante de fígado e ciências biliares, ortopedia e prótese articular, transplante de medula óssea, ciências renais e neurociências. A imagem e o diagnóstico incluem RM, TC e ecoendoscopia.',
	'marengo-asia-hospitals-gurugram':
		'O Marengo Asia Hospitals em Gurugram, antes W Pratiksha Hospital, é um hospital multiespecialidade de cuidados terciários e quaternários com cerca de 250 camas, acreditado pela NABH e NABL. Abrange mais de 21 especialidades, incluindo cardiologia, neurologia, ortopedia, urologia, oncologia, fertilidade, saúde da mulher e cuidados críticos. O Marengo Asia International Institute of Neuro & Spine é o seu centro de excelência, com cirurgia da coluna assistida por robô, e o hospital refere mais de 6000 próteses articulares e 5500 FIV.',
	'fortis-hospital':
		'O Fortis Hospital, Noida, fundado em 2004, é um hospital multiespecialidade de cuidados terciários com 12 blocos operatórios e acreditação NABH. O seu centro cardíaco oferece ECMO, TAVI, LVAD, transplante cardíaco e cirurgia complexa, com duas salas de hemodinâmica, enquanto neurociências e ortopedia utilizam neuronavegação e cirurgia da coluna minimamente invasiva. Gere também programas de transplante de rim e fígado e serviços de oncologia, gastroenterologia, urologia e trauma de urgência.',
	'fortis-hospital-shalimar-bagh':
		'O Fortis Hospital, Shalimar Bagh, inaugurado em 2010, é um hospital multi-superespecialidade de 262 camas num campus de 7,34 acres, acreditado pela NABH e NABL. Os seus centros de excelência abrangem cuidados críticos, urgência e trauma, neurociências, osso e articulação, ciências cardíacas e ciências gastroenterológicas; oferece ainda transplante de rim, obstetrícia e neonatologia com unidade de nível III. A cirurgia robótica e um centro certificado de cirurgia bariátrica estão entre os seus pontos fortes, e é o primeiro hospital indiano registado no Green Building Rating System.',
	'fortis-hospital-faridabad':
		'O Fortis Escorts Hospital, em Faridabad, começou em 1982 como Escorts Heart Institute and Research Centre e integrou a Fortis Healthcare em 2005. Oferece toda a gama de cuidados cardíacos, da cardiologia de intervenção com TAVI e aterectomia à cirurgia de coração aberto e ao transplante cardíaco. Tem também neurociências, ortopedia, urologia, nefrologia, gastroenterologia, cuidados críticos e transplantes de órgãos. Foi o primeiro hospital da cidade a obter a acreditação NABH.',
	'max-hospital':
		'O Max Super Speciality Hospital, Gurugram, perto de HUDA City Centre no Setor 43, é um hospital de superespecialidades compacto, acreditado pela NABH e NABL. Oferece oncologia médica e cirúrgica, cardiologia, ortopedia e prótese articular, nefrologia, neurociências, urologia, cirurgia minimamente invasiva, obstetrícia e ginecologia, pediatria, FIV e cuidados críticos. As suas UCI incluem 12 camas de adultos, além de camas de UCI pediátrica, neonatal e cardíaca, com apoio de endoscopia, radiologia e patologia.',
	'max-super-speciality-hospital-vaishali':
		'O Max Super Speciality Hospital, Vaishali, em Ghaziabad, é um hospital com mais de 387 camas, 128 camas de cuidados críticos, 16 de alta dependência e 14 blocos operatórios modulares. Oferece mais de 37 especialidades clínicas e alberga institutos de neurociências, ciências renais, cuidados oncológicos e ciências cardíacas, além de um centro de trauma e serviços de transplante de rim e fígado. O hospital está acreditado pela NABH e NABL.',
	'max-super-speciality-hospital-noida':
		'Os hospitais da Max Healthcare em Noida estão entre os hospitais multiespecialidade mais avançados da região de Deli-NCR, conhecidos pelas ciências cardíacas, oncologia, neurociências, ortopedia, gastroenterologia e cuidados renais. A unidade principal do Setor 128, de maior dimensão, tem mais de 500 camas, com expansão prevista para 1200; a sua tecnologia inclui o sistema robótico da Vinci Xi, um acelerador linear TrueBeam, RM de 3T e PET-TC. Os hospitais têm acreditação NABH.',
	'max-super-speciality-hospital-dwarka':
		'O Max Super Speciality Hospital, Dwarka, é um hospital de cuidados terciários com mais de 300 camas num campus ecológico de 8,62 acres, um dos primeiros hospitais verdes de Deli NCR com cinco estrelas GRIHA. Tem mais de 120 camas de cuidados críticos, 10 blocos operatórios modulares, uma ala de quimioterapia dedicada e um serviço de urgência muito ativo. As especialidades incluem ciências cardíacas, neurológicas, renais, hepáticas e gastrointestinais, oncologia, ortopedia, cirurgia bariátrica e robótica, otorrinolaringologia e implantes cocleares, e FIV, com o robô da Vinci e uma RM de 3T no local.',
	'max-super-speciality-hospital-shalimar-bagh':
		'O Max Super Speciality Hospital, Shalimar Bagh, criado em 2011, é um grande hospital multi-superespecialidade no noroeste de Deli, acreditado pela JCI e NABH. Oferece mais de 37 especialidades clínicas, incluindo cuidados oncológicos, ciências cardíacas, neurociências, gastroenterologia, ortopedia, nefrologia e urologia, e é conhecido pelo tratamento integral de doenças complexas num só local.',
	'max-smart-super-speciality-hospital':
		'O Max Smart Super Speciality Hospital é um hospital de cuidados terciários de 250 camas na zona institucional de Saket, com cerca de 50 camas de cuidados críticos e 12 blocos operatórios modulares. É um centro de referência para intervenção neurovascular, terapia oncológica dirigida, cirurgia cardíaca e ortopédica, e transplantes de fígado e rim. Dispõe de RM de 3T, angio-TC de 256 cortes, do braço robótico Mako para prótese articular e do sistema da Vinci Xi, e está acreditado pela NABH.',
	'psri-hospital':
		'O Pushpawati Singhania Hospital & Research Institute, criado em 1996 por dois professores do AIIMS, é um hospital multiespecialidade em Sheikh Sarai, no sul de Deli, acreditado pela JCI e NABH. As suas superespecialidades incluem cardiologia e cirurgia cardiotorácica, neurociências, gastroenterologia, programas de transplante de fígado e rim, ortopedia e prótese articular, nefrologia, urologia, pneumologia e medicina do sono, e oncologia. É particularmente conhecido pelos cuidados do fígado, rim, próstata, vesícula biliar, pâncreas e aparelho digestivo.',
	'venkateshwar-hospital':
		'O Venkateshwar Hospital, criado em 2016 em Dwarka, é um hospital de cuidados terciários acreditado pela NABH e NABL, com 125 camas de UCI e 10 blocos operatórios modulares. Abrange mais de 34 especialidades, com centros de excelência em ciências cardíacas, oncologia e transplante de medula óssea, ciências renais, neurociências, e gastroenterologia com transplante de fígado. A tecnologia inclui o sistema de cirurgia robótica Hugo, RM de 3T, TC de 256 cortes, PET-TC, salas de hemodinâmica e aceleradores lineares.',
	'primus-super-speciality-hospital':
		'O Primus Super Speciality Hospital, no enclave diplomático de Chanakyapuri, é um hospital de 250 camas acreditado pela NABH que realiza mais de 3300 cirurgias por ano. Oferece ortopedia, oncologia, gastroenterologia, cardiologia, nefrologia, neurociências, transplantes e urologia, com centros especializados em coluna e ortopedia, cirurgia minimamente invasiva, e neurologia e neurocirurgia. Dispõe de sete blocos operatórios modulares, uma sala de hemodinâmica de painel plano e uma unidade de diálise de 15 camas.',
	'ck-birla-hospital':
		'O CK Birla Hospital em Punjabi Bagh, parte do Grupo CK Birla e inaugurado em 2021, é um hospital multiespecialidade com mais de 230 camas no oeste de Deli, acreditado pela NABH e NABL. Destaca-se pelos serviços materno-infantis, que incluem obstetrícia, uma UCI neonatal de nível III, medicina fetal, fertilidade e FIV, e a primeira estrutura de parto na água do norte da Índia. Oferece também oncologia, ortopedia e coluna, e ciências cirúrgicas avançadas, com cirurgia robótica em ortopedia, urologia e ginecologia.',
	'narayana-hospital':
		'O Narayana Superspeciality Hospital em Gurugram pertence ao grupo Narayana Health, fundado pelo cirurgião cardíaco Dr. Devi Shetty, e tem 215 camas e acreditação NABH. É particularmente forte em ciências cardíacas, com ECMO, TAVI, CRT, transplante cardíaco, cirurgia cardíaca minimamente invasiva e robótica, e angioplastia avançada. O grupo gere também centros de excelência em cancro, neurociências, ortopedia, ciências gastroenterológicas e ciências renais.',
	'asian-institute-of-medical-sciences':
		'O Asian Institute of Medical Sciences, criado em 2010, é um hospital de cuidados terciários de 425 camas em Faridabad, acreditado pela NABH, NABL e AACI. Tem 14 centros de excelência, incluindo o Asian Cancer Centre, o primeiro do norte da Índia a instalar o Varian RapidArc num sistema Trilogy, e um centro de transplante de medula óssea para cancros do sangue e doenças não malignas. Outros pontos fortes são a cardiologia e cirurgia cardíaca, a ortopedia e coluna, as neurociências, o transplante renal e a gastroenterologia.',
	'yatharth-super-speciality-hospital':
		'O Yatharth Super Speciality Hospital, em Noida Extension, criado em 2010, é um hospital de cuidados terciários de 450 camas, com 125 camas de cuidados críticos e 11 blocos operatórios modulares. É descrito como o primeiro e único hospital de Uttar Pradesh com acreditação JCI, e está também acreditado pela NABH. Os seus centros de excelência incluem cardiologia, oncologia, neurociências, urologia, nefrologia, gastroenterologia, e coluna e reumatologia; oferece cirurgia robótica com o sistema da Vinci X.',
	'yashoda-super-speciality-hospitals':
		'O Yashoda Super Speciality Hospital em Kaushambi, Ghaziabad, entrou em funcionamento em 2006 com 100 camas e tem hoje cerca de 300, com acreditações NABH e NABL. Oferece cuidados avançados em mais de 50 especialidades, incluindo neurociências, cardiologia e cirurgia cardiotorácica, prótese articular, pediatria, nefrologia e transplante renal, e gastroenterologia. Um programa de cuidados oncológicos acrescenta cuidados paliativos, gestão da dor, fisioterapia, aconselhamento nutricional e apoio psicológico.',
	'saroj-super-speciality-hospital':
		'O Saroj Super Speciality Hospital em Rohini funciona desde 1997 como hospital multi-superespecialidade com mais de 154 camas no noroeste de Deli; começou como instituto do coração, inaugurado em 2001 pelo presidente K. R. Narayanan. Oferece cirurgia cardíaca, neurologia e neurocirurgia, nefrologia, prótese articular, cirurgia minimamente invasiva, gastroenterologia, cuidados oncológicos e cirurgia plástica e reconstrutiva, com salas de hemodinâmica avançadas e TC multicorte. Está acreditado pela NABH e NABL, funciona 24 horas e tem convénio com mais de 100 seguradoras e organizações.',
	'aakash-hospital':
		'O Aakash Hospital, em Malviya Nagar, fundado em 2004, é um hospital multiespecialidade de 50 camas no sul de Deli, acreditado pela NABH e com certificação ISO 9001. Oferece medicina interna, cirurgia geral e ortopédica, obstetrícia e ginecologia, pediatria e neonatologia, otorrinolaringologia, gastroenterologia, pneumologia, dermatologia e cuidados críticos. A urgência funciona 24 horas e os pacientes podem escolher quartos de luxo, com ar condicionado ou económicos, com tomadas de oxigénio e aspiração junto a cada cama.',
	'sci-international-hospital':
		'O SCI International Hospital, fundado em 2014 em Greater Kailash Parte 1, é um centro cirúrgico de superespecialidade de 50 camas acreditado pela NABH, com quatro blocos operatórios modulares e 15 camas de cuidados críticos. É centro de excelência em urologia e andrologia, FIV e fertilidade, ginecologia e obstetrícia, cirurgia laparoscópica avançada, ortopedia, prótese articular e lesões desportivas, otorrinolaringologia e implantes cocleares, e neonatologia. Oferece também oftalmologia e medicina dentária.',
	'the-signature-advanced-super-speciality-hospital':
		'O The Signature Advanced Super Speciality Hospital, criado em 2019 na rede Park Hospital, é um hospital de 150 camas acreditado pela NABH, perto da autoestrada Dwarka Expressway, no Setor 37D de Gurugram. Oferece ciências cardíacas, ortopedia e prótese articular, neurociências, gastroenterologia, ciências renais e transplante de rim, obstetrícia e ginecologia, pediatria, otorrinolaringologia, oftalmologia e radiologia de intervenção. RM, TC, laboratórios e banco de sangue apoiam a urgência 24 horas.',
	'sci-ivf-hospital':
		'O SCI IVF Hospital é um centro de fertilidade em Greater Kailash, Deli, fundado pelos Drs. Shivani Sachdev Gour e Vishal Dutt Gour e integrado na SCI Healthcare. Oferece FIV, ICSI, IUI, congelação de óvulos, programas de dadores e testes genéticos para a infertilidade masculina e feminina, com laboratório de embriologia próprio. A Dra. Gour foi investigadora clínica em FIV no Hammersmith Hospital, em Londres, e é membro do Royal College of Obstetricians and Gynaecologists (Reino Unido) desde 2005.',
	'nova-ivf-fertility':
		'A Nova IVF Fertility, fundada em 2011, é uma cadeia de centros de fertilidade nas principais cidades indianas, com várias clínicas em Deli NCR, em parceria com a IVI de Espanha. Os serviços incluem IUI, FIV e ICSI, andrologia, vitrificação de óvulos e embriões, eclosão assistida, cultura de blastocistos e teste ERA. Introduziu em Deli o primeiro centro de FIV com embrioscópio de imagem time-lapse, que permite observar o crescimento dos embriões sem intervenção e escolher os melhores.',
	'fortis-ridge-ivf-centre':
		'O Fortis Ridge IVF Centre funciona no Fortis Hospital, Shalimar Bagh, e presta cuidados de fertilidade desde 2010. Realiza FIV, ICSI e IUI, transferência de blastocistos, diagnóstico genético pré-implantação, congelação de embriões e programas de preservação da fertilidade. Uma equipa de cerca de 20 médicos, embriologistas, andrologistas, urologistas, ginecologistas e psicólogos assegura o tratamento completo da infertilidade masculina e feminina.',
	'delhi-ivf-fertility-research-centre':
		'O Delhi IVF & Fertility Research Centre, fundado pelo Dr. Anoop Gupta, é uma das primeiras clínicas de FIV da Índia e trata a infertilidade em Deli desde 1993. Oferece FIV-TE, IUI, ICSI, eclosão assistida, cultura de blastocistos e doação de óvulos e embriões, com um laboratório de embriologia avançado. O centro afirma ter ajudado mais de 21 000 casais de mais de 66 países e disponibiliza coordenadores para pacientes internacionais com visto, alojamento e tradução.',
	'indira-ivf':
		'A Indira IVF foi fundada em 2011 em Udaipur pelo Dr. Ajay Murdia e tornou-se uma das maiores cadeias de FIV da Índia, com mais de 100 centros no país, incluindo Deli e a sua região. Cada centro tem o seu próprio laboratório de embriologia, uma equipa de especialistas e toda a gama de diagnósticos e tratamentos de fertilidade, como IUI, FIV e ICSI. O grupo afirma ter ajudado mais de 200 000 casais e tem mais de 340 médicos especialistas em FIV.',
	'cloudnine-ivf-centre-kailash-colony':
		'A Cloudnine Fertility em Kailash Colony integra o grupo Cloudnine, que também presta cuidados de maternidade, ginecologia, pediatria e neonatologia. O centro, acreditado pela NABH, oferece FIV, ICSI, FIV com óvulos de dadora, transferência de embriões congelados, congelação de óvulos e diagnóstico genético pré-implantação, além de aconselhamento psicológico. Os serviços para pacientes internacionais incluem apoio com o visto, intérpretes e coordenação da viagem, com assistência de urgência 24 horas.',
	'international-fertility-centre':
		'O International Fertility Centre, com sede em Nova Deli e dirigido pela fundadora, a Dra. Rita Bakshi, é uma das clínicas de fertilidade mais antigas da Índia e uma rede de mais de 10 clínicas de FIV na Índia e no Nepal. O centro de Green Park oferece FIV, ICSI, IUI, doação de óvulos e esperma, PGD/PGS e endoscopia para a saúde da mulher. A Dra. Bakshi tem mais de 37 anos de experiência em infertilidade e o centro realiza mais de 1000 ciclos de FIV e ICSI por ano na sede.',
	'laimaa-fertility-ivf-surrogacy-clinic':
		'A Laimaa Fertility, criada em 2022, é uma clínica de fertilidade em Greater Kailash Parte II fundada pela embriologista Pooja Agarwal com as médicas Akanksha Chauhan e Mamta Chahar. Oferece FIV, ICSI, IUI, congelação de óvulos e embriões, doação de óvulos e soluções cirúrgicas para a infertilidade, e é conhecida por casos complexos como AMH baixa e infertilidade masculina grave. O seu trabalho de embriologia inclui TESA-ICSI, PICSI, transferência de blastocistos e biópsia embrionária.',
	'gaudium-ivf':
		'A Gaudium IVF and Women Health foi fundada em 2009 pela Dra. Manika Khanna, especialista em infertilidade e cirurgiã laparoscópica, e tem hoje cerca de 36 centros em seis estados indianos, incluindo South Extension em Deli. Oferece FIV, congelação de óvulos e embriões, e tratamento de falhas repetidas de FIV, infertilidade masculina e endometriose. O seu laboratório de embriologia usa ferramentas assistidas por IA, como o SiD para a avaliação do esperma e o ERICA para a dos embriões.',
	'pristyn-care-ferticity-super-speciality-ivf-hospital':
		'O Pristyn Care Ferticity Super Speciality & IVF Hospital, em Malviya Nagar, oferece a casais FIV, IUI, ICSI, congelação de óvulos e embriões e tratamentos com dadores. Trata o SOP, a obstrução tubária, a baixa reserva ovárica, a infertilidade masculina, a endometriose e os abortos de repetição, e realiza indução da ovulação e avaliações hormonais detalhadas. A clínica consta do registo de clínicas de TRA do ICMR e a cofundadora, a Dra. Ila Gupta, tem mais de 29 anos de experiência.',
	'nova-ivf-fertility-centre-rajouri-garden':
		'O centro Nova IVF Fertility de Rajouri Garden é uma das clínicas do grupo no oeste de Deli e abre de segunda a sábado. Trata a infertilidade masculina, a infertilidade inexplicada, a baixa reserva ovárica, o SOP, a endometriose e a infertilidade por fator tubário com IUI, FIV, ICSI e seleção espermática MACS. Entre os médicos está a Dra. Aswati Nair, ginecologista e especialista em FIV com mais de 17 anos de experiência em endometriose, falhas repetidas de FIV e abortos de repetição.',
	'elixir-fertility-centre':
		'O Elixir Fertility Centre, criado em 2014, é uma clínica de fertilidade em Gujranwala Town, no norte de Deli. Oferece FIV, ICSI, IUI e análise de sémen, com laboratório de diagnóstico e ecografia próprios. A equipa inclui o Dr. Puneet Kochhar, ginecologista e especialista em FIV que trabalhou na Bourn Hall Clinic, em Cambridge (Reino Unido), e lecionou no Lady Hardinge Medical College, em Deli.',
	'femmenest-fertility-ivf-centre':
		'A Femmenest é um centro de saúde da mulher e fertilidade em Anand Vihar, no leste de Deli, que oferece FIV, IUI, ICSI e apoio personalizado a casais. Presta também cuidados ginecológicos para o SOP, desequilíbrios hormonais e check-ups de saúde feminina, com diagnóstico, terapêuticas hormonais e tratamento completo da infertilidade num só local. A equipa inclui médicos de fertilidade, embriologistas clínicos e enfermeiras dedicadas, e a clínica abre seis dias por semana e ao domingo de manhã.',
	'india-ivf-clinic':
		'A India IVF Clinic, em Vasant Vihar, é uma clínica de fertilidade integrada na rede Fortis, com presença em consulta no Fortis Flt. Lt. Rajan Dhall Hospital, em Vasant Kunj. Oferece FIV e cirurgia para melhorar a fertilidade, com uma equipa liderada por especialistas como a Dra. Richika Sahay. Os pacientes elogiam o pessoal atencioso e o acompanhamento pessoal, e a clínica tem acesso para cadeiras de rodas e estacionamento.',
	'spruce-dental':
		'A Spruce Dental, em Jasola Vihar, é uma clínica dentária do sul de Deli que oferece endodontia sem dor, implantes dentários unitários e de boca completa, branqueamento, opções de ortodontia e transformações do sorriso. Usa imagem digital para um diagnóstico preciso e planeamento do tratamento. A clínica integra o grupo Spruce Dental, dirigido pelo implantologista e ortodontista Dr. Javed Rizwan.',
	'zemya-ivf-fertility-clinics':
		'As Zemya IVF & Fertility Clinics, em Green Park Extension, oferecem FIV, IUI, ICSI, cuidados da infertilidade masculina, congelação de óvulos e preservação da fertilidade sob o mesmo teto. O centro tem blocos operatórios modulares, um laboratório de FIV moderno, um laboratório de andrologia avançado, um laboratório de patologia, farmácia e uma sala para pacientes internacionais, com consultas por vídeo. A sua equipa de especialistas com formação internacional e embriologistas certificados pela ESHRE afirma ter ajudado mais de 50 000 casais.',
	'kokilaben-dhirubhai-ambani-hospital':
		'O Kokilaben Dhirubhai Ambani Hospital, em Andheri West (Bombaim), começou a funcionar em 2009 como hospital multiespecialidade de 750 camas, com cerca de 180 camas de UCI, acreditado pela JCI, NABH e CAP. O seu Centro de Cirurgia Robótica, criado em 2012, usa hoje o da Vinci Xi e o primeiro sistema robótico Toumai da Índia em oncologia, urologia, ginecologia e cirurgia digestiva. A tecnologia avançada e os centros de excelência são um foco do hospital, que atende pacientes de toda a Índia e do estrangeiro.',
	'p-d-hinduja-hospital':
		'O P. D. Hinduja Hospital foi fundado em 1951 por Parmanand Deepchand Hinduja em colaboração com o Massachusetts General Hospital, e mudou-se em 1963 para o edifício da ala Este de Mahim. É um hospital multiespecialidade de cuidados terciários com mais de 45 especialidades, 53 camas de cuidados críticos e 19 unidades de dia, incluindo cardiologia, oncologia, neurologia e ortopedia. Ministra cursos DNB em 26 especialidades, programas de enfermagem e ciências da saúde, e colabora com instituições como a Stanford University e os Hospitais Universitários de Genebra.',
	'fortis-hospital-mulund':
		'O Fortis Hospital, Mulund, inaugurado em 2002, é um hospital multiespecialidade de cuidados quaternários com 400 camas e várias reacreditações JCI. É reconhecido como o maior centro de transplantes de Maharashtra, com transplantes de rim, fígado, coração e medula óssea, e é conhecido por neurociências, ciências cardíacas, oncologia, nefrologia, urologia e ortopedia. O serviço de urgência e o centro de trauma de nível 1 têm acreditação NABH, e a oncologia usa o acelerador linear Versa HD.',
	'jaslok-hospital':
		'O Jaslok Hospital & Research Centre, fundado pelo filantropo Seth Lokoomal Chanrai e pelo cirurgião Shantilal Jamnadas Mehta, foi inaugurado em 1973 pela primeira-ministra Indira Gandhi. É um dos hospitais terciários de fundação mais antigos do país, com mais de 350 camas, cerca de 50 especialidades e quase 20 clínicas especializadas. Lançou o primeiro serviço de urologia privado da Índia e realizou um primeiro transplante renal, e é conhecido pela cardiologia, neurologia, ortopedia, oncologia, reprodução assistida e transplantes multiorgânicos.',
	'nanavati-max-super-speciality-hospital':
		'O Nanavati Max Super Speciality Hospital, em Vile Parle, foi inaugurado em 1950 pelo primeiro-ministro Jawaharlal Nehru e abriu aos pacientes em 1951. Tem 350 camas, 55 departamentos de especialidade e mais de 350 consultores, com centros de excelência em cardiologia, oncologia, nefrologia, ortopedia, cirurgia da coluna, neurologia, bariátrica e gastroenterologia cirúrgica. O centro de imagem inclui uma RM de 3T e um PET-TC de 64 cortes, e o hospital está acreditado pela NABH e NABL.',
	'apollo-hospitals-greams-road':
		'O Apollo Hospitals, Greams Road, abriu em 1983 e é o hospital Apollo original; é hoje uma unidade de 550 camas acreditada pela JCI e NABH. Tem mais de 12 centros de excelência, incluindo o Apollo Heart Institute, o Institute of Liver Sciences, o Institute of Neurosciences e o Institute of Robotic Surgery, além de programas de transplante de grande volume de fígado, rim, coração e pulmão. A tecnologia inclui o sistema da Vinci e radioterapia TrueBeam, e o seu centro de protonterapia é descrito como o primeiro da Índia.',
	'miot-international':
		'O MIOT International, o Madras Institute of Orthopaedics and Traumatology, foi fundado pelo Prof. P. V. A. Mohandas em fevereiro de 1999 como um hospital de 70 camas e cresceu para um campus de cuidados quaternários de 1000 camas, com 63 especialidades e 21 blocos operatórios. O seu departamento de ortopedia e prótese articular foi classificado como o primeiro da Índia pela Outlook Health, e gere também centros de transplante de fígado e medula óssea, oncologia, cuidados cardíacos e nefrologia. Recebeu pacientes de mais de 130 países e está acreditado pela NABH e NABL.',
	'gleneagles-global-health-city':
		'O Gleneagles Global Health City, em Perumbakkam, é um grande hospital de transplante multiorgânico e cuidados quaternários num campus de 21 acres, parte da IHH Healthcare, com mais de 40 especialidades. Realiza transplantes de fígado, rim, coração, pulmão e medula óssea, com mais de 500 transplantes hepáticos referidos, e conduz o programa hepático em colaboração com o King\'s College Hospital, em Londres. A oncologia, a hepatologia, as neurociências e os cuidados de trauma são outros pontos fortes, e o hospital tem acreditação NABH.',
	'fortis-malar-hospital':
		'O Fortis Malar Hospital, em Adyar, é um hospital multiespecialidade de cuidados terciários com 180 camas e mais de 40 especialidades, antigo Malar Hospital e parte da Fortis Healthcare desde 2007. É particularmente conhecido pelos cuidados cardíacos, que abrangem cardiologia de intervenção, não invasiva e pediátrica, cirurgia cardiovascular e um programa de transplante cardíaco que apresenta como um dos maiores da Ásia. Oferece também neurologia, neurocirurgia, ortopedia, nefrologia, gastroenterologia e urologia, e está acreditado pela NABH.',
	'kauvery-hospital':
		'O Kauvery Hospital, em Alwarpet, é um hospital multiespecialidade de 300 camas no centro de Chennai, parte do grupo Kauvery e com acreditação NABH. Tem centros de excelência em ciências cardíacas, neurociências, gastroenterologia, transplante de órgãos, ortopedia e saúde da mulher; o Kauvery Heart Institute trata angioplastia complexa, cirurgia de bypass híbrida e transplantes cardíacos. O Kauvery Institute of Robotic Surgery oferece procedimentos robóticos da Vinci em oncologia, urologia, cirurgia colorretal, cardíaca e hepática, e transplante de rim.',
	'manipal-hospital-old-airport-road':
		'O Manipal Hospital, Old Airport Road, serve Bengaluru desde 1991 e é o hospital de referência da rede Manipal Hospitals, com 144 camas de cuidados intensivos e 20 blocos operatórios modulares. Oferece mais de 60 superespecialidades, com centros de excelência em oncologia, ciências cardíacas, neurociências, gastroenterologia, ortopedia e transplante de órgãos. O programa de transplante multiorgânico abrange rim, fígado, pâncreas e coração, e foi dos primeiros da Índia a adotar o transplante renal assistido por robô. O hospital tem acreditação NABH e JCI.',
	'sakra-world-hospital':
		'O Sakra World Hospital, inaugurado em fevereiro de 2014, é um hospital multi-superespecialidade de 350 camas em Bengaluru, uma joint venture entre a Kirloskar, a Toyota Tsusho e a Secom Hospitals do Japão. Oferece neurologia, cardiologia, ortopedia, cirurgia da coluna, ciências renais, oncologia, obstetrícia e ginecologia, ciências da reabilitação e pediatria, e é conhecido pelos transplantes de órgãos. Os protocolos de enfermagem combinam a prática indiana e japonesa, e a imagem inclui RM, TC multidetetor e radiografia digital.',
	'narayana-institute-of-cardiac-sciences':
		'O Narayana Institute of Cardiac Sciences, posto em funcionamento em 2000 no NH Health City (Bommasandra) pelo Dr. Devi Shetty, é o hospital cardíaco de referência da Narayana Health e um dos maiores hospitais cardíacos do mundo. Tem 19 blocos operatórios cardíacos, dois deles robóticos, e oito salas de hemodinâmica, incluindo uma híbrida. O hospital realiza mais de 40 cirurgias cardíacas por dia, cerca de 16 delas pediátricas, e está acreditado pela JCI e NABH.',
	'fortis-hospital-bannerghatta-road':
		'O Fortis Hospital, Bannerghatta Road, é o hospital de referência da Fortis Healthcare no sul da Índia, com cuidados terciários de superespecialidade em 40 áreas e, segundo se refere, o primeiro de Karnataka a obter a acreditação JCI. Os seus centros de excelência incluem cardiologia e cirurgia cardíaca, neurociências, oncologia, ortopedia, transplante de órgãos, gastroenterologia, pediatria e cuidados críticos. A oncologia oferece PET-TC, cirurgia oncológica robótica e HIFU para o cancro da próstata, e o Fortis Institute of Robotic Surgery é um centro de excelência.',
	'aster-cmi-hospital':
		'O Aster CMI Hospital, em Hebbal (Bengaluru), faz parte da Aster DM Healthcare e oferece perto de 500 camas, dos cuidados primários aos quaternários, com acreditações NABH e NABL. Os seus centros de excelência incluem ciências cardíacas, neurociências, gastroenterologia, cuidados hepáticos integrados, transplante de órgãos, urologia e nefrologia, ortopedia, saúde da mulher e saúde infantil. O Aster International Institute of Oncology oferece protonterapia, cirurgia robótica e HIPEC, e o programa de transplantes realiza transplantes renais robóticos.',
	'apollo-hospitals-jubilee-hills':
		'O Apollo Hospitals, Jubilee Hills, fundado em 1988, é o hospital de referência da Apollo em Hyderabad e tem acreditação JCI, NABH e NABL. Tem 12 centros de excelência, incluindo ciências cardíacas (três salas de hemodinâmica e cirurgia cardíaca robótica), um centro oncológico com cirurgia oncológica robótica e neurociências com RM intraoperatória e robótica da coluna. A equipa de transplantes trata fígado, rim, coração e medula óssea, com o apoio de uma unidade de hemato-oncologia.',
	'continental-hospitals':
		'O Continental Hospitals, fundado em 2013 no distrito financeiro de Hyderabad, é um hospital de 585 camas com mais de 50 especialidades em 18 pisos, acreditado pela JCI, NABH e NABL. É descrito como o primeiro hospital de superespecialidade indiano com certificação LEED, com blocos operatórios verdes e unidades NICU e PICU de nível 3. É conhecido pelos transplantes de órgãos complexos, ciências cardíacas, neurociências, oncologia e ortopedia, e os seus cirurgiões realizaram em abril de 2023 o primeiro bypass coronário assistido por robô da Índia.',
	'yashoda-hospitals-somajiguda':
		'O Yashoda Hospitals, Somajiguda, é o primeiro hospital do grupo Yashoda e começou em 1994, com mais de 400 camas e acreditação NABH. Os seus centros de excelência incluem coração e cirurgia cardiotorácica, neurociências, cancro, transplantes de fígado e multiorgânicos, osso e articulação, nefrologia, ciências robóticas, cirurgia da coluna, cuidados materno-infantis e fertilidade. Laboratório, diagnóstico e farmácia funcionam 24 horas por dia.',
	'global-hospitals-hyderabad':
		'O Gleneagles Global Hospitals, em Lakdi-ka-pul, conhecido como Global Hospitals, foi o primeiro hospital Gleneagles Global de Hyderabad e faz parte do grupo fundado em 1999 pelo Dr. K. Ravindranath. É mais conhecido pelos transplantes de fígado, rim, coração e pulmão, e refere o primeiro transplante hepático dividido e auxiliar bem-sucedido da Índia. Os blocos operatórios permitem cirurgia robótica e minimamente invasiva, com UCI especializadas, incluindo uma UCI hepática e uma unidade pós-transplante.',
	'kims-hospitals-secunderabad':
		'O KIMS Hospitals, Secunderabad, abriu em 2004 como hospital de referência de cuidados terciários e quaternários de 1000 camas, sob a liderança do Dr. Bhaskar Rao Bollineni. Oferece cardiologia, gastroenterologia e hepatologia, neurociências, transplante de órgãos, oncologia, ortopedia, urologia, fertilidade e cirurgia bariátrica. O programa de transplantes abrange coração, pulmão, fígado, rim e medula óssea, com um primeiro transplante cardíaco em 2012 e 1000 transplantes renais registados em 2019; tem acreditação NABH.',
	'amrita-institute-of-medical-sciences-kochi':
		'O Amrita Hospital em Kochi, antes Amrita Institute of Medical Sciences, foi fundado em 1998 por Mata Amritanandamayi Devi (Amma) como hospital terciário multiespecialidade de referência e ensino. Tem 29 departamentos de especialidade e 17 centros de excelência, com um vasto corpo docente e pessoal de apoio, e atende mais de um milhão de pacientes em ambulatório e cerca de 70 000 internados por ano. Os laboratórios estão acreditados pela NABL e o hospital tem acreditação NABH.',
	'aster-medcity':
		'O Aster Medcity, em Cheranalloor (Kochi), é um grande hospital de cuidados quaternários num campus de 40 acres junto aos remansos, e o primeiro hospital multiespecialidade quaternário do Kerala acreditado pela JCI. Tem oito centros de excelência, incluindo neurociências, ciências cardíacas, ortopedia, oncologia, gastroenterologia, nefrologia e urologia, saúde da mulher e transplante multiorgânico. O programa de cirurgia robótica minimamente invasiva com o sistema da Vinci refere mais de 5000 cirurgias assistidas por robô.',
	'lakeshore-hospital':
		'O VPS Lakeshore Hospital, em Nettoor (Kochi), é um hospital multi-superespecialidade que começou a funcionar como hospital multiespecialidade em 2003 e está acreditado pela NABH. Oferece mais de 30 departamentos clínicos, incluindo transplante multiorgânico, gastroenterologia, prótese articular, cardiologia e cirurgia cardiovascular, e neurologia. O departamento de nefrologia e transplante renal realizou mais de 1600 transplantes, e o hospital cita o primeiro transplante pediátrico de medula óssea e o primeiro transplante de fígado do Kerala.',
	'kims-health-kochi':
		'O KIMS Health, Kochi, em Edappally, é o hospital de Kochi do grupo KIMS com sede em Thiruvananthapuram, com 125 camas e cerca de 25 departamentos. Oferece serviços de ambulatório e internamento com laboratório, farmácia, radiografia e ECG 24 horas por dia, assegurados por consultores experientes e pessoal de enfermagem treinado. O hospital está acreditado pela NABH e pelo Australian Council on Healthcare Standards International.',
	'apollo-multispeciality-hospitals-kolkata':
		'O Apollo Multispeciality Hospitals, em Canal Circular Road, inaugurado em 2003, é um hospital de 700 camas com mais de 50 especialidades e 33 centros de excelência, e o único hospital do leste da Índia com acreditação JCI. Os seus centros incluem cuidados cardíacos, oncologia, ortopedia, gastroenterologia, neurociências, transplantes, robótica e urgência. Levou ao leste da Índia o transplante renal totalmente robótico, com programas de transplante de dador vivo e cadáver.',
	'amri-hospitals-dhakuria':
		'O AMRI Hospitals, Dhakuria, começou em 1996 como uma parceria público-privada com o Governo de Bengala Ocidental e passou de consultas externas a um grande hospital multiespecialidade, agora parte do Manipal Hospitals após a aquisição de uma participação maioritária em 2023. É conhecido pelas ciências cardíacas, prótese articular, cuidados de trauma, FIV, cirurgia maxilofacial e cirurgia plástica, com urgência e cuidados críticos como centro de excelência. A imagem e radioterapia avançadas incluem PET-TC, SPECT-TC, IMRT e VMAT, e o hospital está acreditado pela NABH.',
	'fortis-hospital-anandapur':
		'O Fortis Hospital, Anandapur, fundado em 2011, é um hospital de 10 pisos num terreno de 7 acres, com cerca de 300 camas. Oferece cardiologia e cirurgia cardíaca, neurociências, ortopedia, nefrologia, urologia, pneumologia, cuidados digestivos e cuidados materno-infantis, com clínicas especializadas em hipertensão pulmonar e alergias. O centro cardíaco dispõe de quatro salas de hemodinâmica, uma UCI cirúrgica de 14 camas e uma unidade coronária de 20 camas, e o hospital tem acreditação NABH e NABL.',
	'medica-superspecialty-hospital':
		'O Medica Superspecialty Hospital, em Mukundapur, criado em 2010, é um grande hospital de cuidados terciários, dos mais respeitados do leste da Índia, com 18 departamentos e oito centros de excelência. Os seus serviços incluem cardiologia e cirurgia cardíaca, neurociências, gastroenterologia e doenças do fígado, nefrologia, oncologia, ortopedia, pediatria e neonatologia, e uma das unidades de cuidados críticos mais avançadas da região. Tornou-se em 2022 o primeiro centro oficial de formação em cirurgia robótica do leste da Índia e tem um laboratório acreditado pela NABL com laboratório molecular.',
	'zydus-hospitals':
		'O Zydus Hospitals, criado em 2015 na S.G. Highway, é um hospital de superespecialidades de 550 camas em 16 pisos, acreditado pela NABH e NABL. Os seus centros de excelência incluem FIV, prótese articular, cuidados oncológicos, neurologia e neurocirurgia, cirurgia cardíaca, transplantes de rim e fígado, e cirurgia plástica. O programa de transplante hepático conta com uma equipa multidisciplinar de mais de 20 especialistas, e em todos os seus centros o Zydus refere mais de 430 transplantes de rim e 295 de fígado.',
	'cims-hospital':
		'O CIMS Hospital, agora Marengo Asia CIMS Hospital, abriu em 2010 junto a Science City Road em Ahmedabad; é um hospital verde multi-superespecialidade acreditado pela JCI, NABH e NABL. As suas especialidades incluem cuidados oncológicos, ciências cardíacas, gastroenterologia, transplante de fígado, ortopedia e prótese articular, ciências renais, neurociências, transplante de medula óssea e cirurgia bariátrica. Liderado em cirurgia cardíaca pelo Dr. Dhiren Shah, primeiro cirurgião a realizar um transplante de coração no Gujarate, tem um centro de transplantes de coração, pulmão, fígado, rim e medula óssea pediátrica.',
	'sterling-hospital':
		'O Sterling Hospital, em Gurukul (Ahmedabad), integra uma rede de hospitais privados do Gujarate e foi o primeiro hospital do estado a obter a acreditação NABH completa, em 2009. Oferece ciências cardíacas, oncologia (cirúrgica, médica e radioterapia), cuidados críticos e pneumologia, gastroenterologia e cirurgia digestiva, neurociências e cirurgia da coluna, nefrologia e urologia, ortopedia e prótese articular, e cirurgia bariátrica. As UCI pediátrica e neonatal estão equipadas com monitorização multiparamétrica, ventiladores e ECMO.',
	'shalby-hospitals':
		'O Shalby Hospitals começou em Ahmedabad em 1994 como um centro de prótese articular criado pelo Dr. Vikram I. Shah e tornou-se uma cadeia de hospitais multiespecialidade. O hospital de SG Highway, fundado em 2007 e acreditado pela NABH e NABL, é conhecido em todo o mundo pela ortopedia, com mais de 150 000 próteses articulares realizadas em todo o grupo. A técnica ZERO do Dr. Shah reduziu o tempo cirúrgico de uma prótese do joelho para cerca de 10 a 12 minutos.',
	'dr-agarwal-s-eye-hospital':
		"O Dr. Agarwal's Eye Hospital foi fundado em 1957 em Chennai pelo Dr. Jaiveer Agarwal (Padma Bhushan) e pela Dra. Tahira Agarwal, e tornou-se uma das maiores cadeias de cuidados oculares da Índia, com centros em muitos estados indianos e no estrangeiro. Oferece cirurgia de cataratas, incluindo técnicas assistidas por laser de femtossegundo, LASIK e outra cirurgia refrativa, cuidados da retina (retinopatia diabética, descolamento da retina), glaucoma, córnea e oftalmologia pediátrica, e gere vários centros em Deli-NCR.",
};
